INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('d2245a99-93d8-4cee-86c3-9eb6810084a3', '35ee2a96-2d5e-4d03-83a2-bbda7f5ed292', 3, 'Match each figurative language term with its corresponding example.', 'matching', 'Figurative Language', 'medium', 4, NULL, 'Alliteration -> Peter Piper picked a peck of pickled peppers.; Hyperbole -> I have told you a million times to clean your room.; Oxymoron -> Deafening silence filled the room.; Onomatopoeia -> The bacon sizzled softly in the pan.', '{"left_items": ["Alliteration", "Hyperbole", "Oxymoron", "Onomatopoeia"], "right_items": ["Deafening silence filled the room.", "The bacon sizzled softly in the pan.", "Peter Piper picked a peck of pickled peppers.", "I have told you a million times to clean your room."], "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
