INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('a71f1169-3615-4693-afec-fce4a577110e', '35ee2a96-2d5e-4d03-83a2-bbda7f5ed292', 6, 'Identify the structural components of a standard academic argumentative essay based on their descriptions.', 'labeling', 'Essay Writing Structure', 'medium', 3, NULL, 'Part A: Hook; Part B: Thesis Statement; Part C: Topic Sentence', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": ["Part A: The opening sentence designed to capture the reader''s attention.", "Part B: The central claim or argument presented at the end of the introduction.", "Part C: The sentence at the start of a body paragraph that introduces its main topic."], "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('4bdfa717-4c16-4952-9c9c-1c5ada04eb18', '35ee2a96-2d5e-4d03-83a2-bbda7f5ed292', 7, 'Explain the key distinction between a word''s denotation and its connotation. Provide a brief example to illustrate your point.', 'short_answer', 'Semantics and Word Choice', 'medium', 4, NULL, 'Denotation is the explicit, literal dictionary definition of a word, while connotation refers to the implied emotional, cultural, or social associations attached to it. For example, ''inexpensive'' and ''cheap'' both denote low cost, but ''cheap'' carries a negative connotation of poor quality.', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('6b19f76a-58d7-425b-b875-5309c75897cb', '35ee2a96-2d5e-4d03-83a2-bbda7f5ed292', 8, 'Calculate the total number of metrical syllables in a traditional 14-line Shakespearean Sonnet written strictly in iambic pentameter (10 syllables per line).', 'calculation', 'Poetic Meter and Scansion', 'easy', 3, NULL, '140', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": null, "expected_units": "syllables"}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('8b6da6d7-1f8b-4033-9693-4af8d8df2fdc', '35ee2a96-2d5e-4d03-83a2-bbda7f5ed292', 9, 'Analyze how William Shakespeare utilizes light and dark imagery in ''Romeo and Juliet'' to reflect the conflicting themes of love and impending tragedy. Support your essay with specific textual references and structural analysis.', 'essay', 'Literary Analysis', 'hard', 20, NULL, 'High-scoring responses must include: 1) Clear, analytical thesis statement connecting light/dark motifs to conflict/tragedy. 2) Analysis of specific examples (e.g., Juliet as the sun, torches burning bright, night as a disguise and place of safety vs. day bringing danger). 3) Explanation of paradoxes (light bringing doom, darkness offering unity). 4) Well-structured paragraphs, textual evidence/quotes, and strong command of analytical prose.', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
