INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('ad7f41e5-99d9-466c-9cc4-2c629ef6f766', 'd5125715-6864-41f8-a502-4184d5baf881', 5, 'Match each commercial trading document with its primary function in home trade.', 'matching', 'Trading Documents', 'medium', 4, NULL, 'Quotation -> Sent by seller detailing product prices and credit terms prior to order; Delivery Note -> Accompanies goods delivered to check contents against order; Invoice -> Requests payment for goods supplied on credit; Credit Note -> Issued to rectify an overcharge or for returned goods', '{"left_items": ["Quotation", "Delivery Note", "Invoice", "Credit Note"], "right_items": ["Issued to rectify an overcharge or for returned goods", "Sent by seller detailing product prices and credit terms prior to order", "Accompanies goods delivered to check contents against order", "Requests payment for goods supplied on credit"], "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('53141d29-df2c-4123-b74f-4088ca0b9d63', 'd5125715-6864-41f8-a502-4184d5baf881', 6, 'Categorize the following financial sources into Short-term Finance or Long-term Finance.', 'categorization', 'Sources of Finance', 'medium', 6, NULL, 'Short-term Finance: Trade credit, Bank overdraft, Factoring; Long-term Finance: Mortgage, Debentures, Venture capital', '{"left_items": null, "right_items": null, "items": ["Trade credit", "Mortgage", "Bank overdraft", "Debentures", "Factoring", "Venture capital"], "categories": ["Short-term Finance", "Long-term Finance"], "label_prompts": null, "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('bfd351fc-786c-4d8c-81bd-2ac0b4382e3f', 'd5125715-6864-41f8-a502-4184d5baf881', 7, 'Arrange the steps of the traditional chain of distribution in the correct sequential order from extraction to final consumer.', 'ordering', 'Chain of Distribution', 'medium', 4, NULL, '1. Primary sector extracts raw materials, 2. Secondary sector manufactures finished goods, 3. Wholesaler buys bulk quantities from manufacturer, 4. Retailer sells products to local consumers', '{"left_items": null, "right_items": null, "items": ["Retailer sells products to local consumers", "Wholesaler buys bulk quantities from manufacturer", "Primary sector extracts raw materials", "Secondary sector manufactures finished goods"], "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('159a6caf-5dac-40f9-9419-ef1e94614e8c', 'd5125715-6864-41f8-a502-4184d5baf881', 8, 'Identify the missing components (Part A, Part B, and Part C) in the formula used to calculate Return on Capital Employed (ROCE): ROCE = ( [Part A] / [Part B] ) * [Part C]', 'labeling', 'Measuring Commercial Performance', 'medium', 3, NULL, 'Part A: Profit for the year (net profit); Part B: Capital Employed; Part C: 100', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": ["Part A", "Part B", "Part C"], "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('6389031f-1f23-4ec4-8f99-9d35c7158fdd', 'd5125715-6864-41f8-a502-4184d5baf881', 9, 'Explain one benefit to a retail business of adopting a ''bricks and clicks'' operational model.', 'short_answer', 'Ecommerce and Retailing', 'medium', 3, NULL, 'By selling online as well as through physical stores (1), a business can reach a much broader geographical market (1), which increases customer accessibility and total sales revenue (1).', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('2dda94b5-efc2-4868-ada8-5fc19e9fb239', 'd5125715-6864-41f8-a502-4184d5baf881', 10, 'Belluni is a clothing retailer in Vietnam experiencing increased demand. It needs to restock its store and is evaluating two options: Option 1: Buying direct from a local supplier; Option 2: Buying through a wholesaler. Justify which option Belluni should choose.', 'essay', 'Buying and Selling', 'hard', 9, NULL, 'Option 1 (Direct Buying): Lower unit costs by eliminating intermediary margins and direct negotiation on custom designs, but requires larger order sizes and higher transport costs. Option 2 (Wholesaler): Ability to buy smaller quantities as needed and reduced storage/inventory costs, but unit purchase prices may be higher. AJIM Judgment: Belluni should choose Option 1 because maintaining brand reputation and high quality clothing is key, and direct contact with local suppliers ensures faster access to custom designs.', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('399f4284-050c-4324-8507-03ea0f525a65', 'd5125715-6864-41f8-a502-4184d5baf881', 11, 'Evaluate why it is important for a consumer electronics manufacturer like Nintendo to ensure that the goods it sells are free from faults. Use your knowledge of commerce and consumer protection in your response.', 'essay', 'Consumer Protection Legislation', 'hard', 12, NULL, 'AO1: Consumer protection laws require goods to be safe and fit for purpose. AO2: Nintendo sells electronic consoles/accessories which could cause injury or fire if faulty. AO3: Complying avoids legal fines, costly recalls, and negative publicity on gaming sites/social media. AO4: However, rigorous quality control and safety compliance increases production costs. Overall Conclusion: Safety compliance is paramount because bad publicity and product recall costs would far outweigh the investment in quality assurance.', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
