INSERT INTO questions (id, exam_id, question_index, question_text, question_type, topic, difficulty, marks, options, correct_answer, metadata) VALUES ('51b1f73d-ec82-478d-a80c-da83c7a58502', '1f9d2714-4fa3-4754-a5a3-4987379d5add', 9, 'Describe three different ways human activities can harm a forest ecosystem. Then, propose two practical actions humans can take to help protect or restore forest environments.', 'essay', 'Environmental Science', 'hard', 6, NULL, 'Harmful activities (3 required): Deforestation/cutting down trees for land, littering/chemical pollution, overhunting local wildlife, or introducing invasive species. Actions to protect/restore (2 required): Planting new trees (reforestation), establishing protected wildlife parks, recycling paper products, or participating in clean-up events.', '{"left_items": null, "right_items": null, "items": null, "categories": null, "label_prompts": null, "expected_units": null}'::jsonb);
